tools.example:
model.component("comp1").physics().create("es", "Electrostatics", "geom1");
model.component("comp1").physics("es").create("gnd1", "Ground", 2);
model.component("comp1").physics("es").feature("gnd1").selection().set(new int[]{3, 8});
model.component("comp1").physics("es").create("pot1", "ElectricPotential", 2);
model.component("comp1").physics("es").feature("pot1").selection().set(new int[]{4});
model.component("comp1").physics("es").feature("pot1").set("V0", "1[V]");
model.component("comp1").physics("es").feature("ccn1").set("epsilonr_mat", "userdef");

model.component("comp1").physics().create("ec", "ConductiveMedia", "geom1");
model.component("comp1").physics("ec").create("term1", "Terminal", 2);
model.component("comp1").physics("ec").feature("term1").selection().set(new int[]{1});
model.component("comp1").physics("ec").feature("term1").set("TerminalType", "Voltage");
model.component("comp1").physics("ec").feature("term1").set("V0", "20[mV]");
model.component("comp1").physics("ec").create("gnd1", "Ground", 2);
model.component("comp1").physics("ec").feature("gnd1").selection().set(new int[]{7});

model.component("comp1").physics().create("mf", "InductionCurrents", "geom1");
model.component("comp1").physics("mf").create("coil1", "Coil", 3);
model.component("comp1").physics("mf").feature("coil1").selection().set(new int[]{2});
model.component("comp1").physics("mf").feature("coil1").set("ConductorModel", "Multi");
model.component("comp1").physics("mf").feature("coil1").set("N", "100");
model.component("comp1").physics("mf").feature("coil1").set("ICoil", "1[A]");

model.component("comp1").physics().create("mfnc", "MagnetostaticsNoCurrents", "geom1");
// GUI: Magnetic Fields, No Currents (mfnc) > Magnetic Flux Conservation 1 -
// set Constitutive relation = Remanent flux density and enter B_r for the magnet domain;
// right-click > Force Calculation on the magnet to get mfnc.Forcex/y/z.
model.study("std1").create("stat", "Stationary");

model.component("comp1").physics().create("emw", "ElectromagneticWaves", "geom1");
model.component("comp1").physics("emw").create("lport1", "LumpedPort", 2);
model.component("comp1").physics("emw").feature("lport1").selection().set(new int[]{5});
model.component("comp1").physics("emw").create("pec2", "PerfectElectricConductor", 2);
model.component("comp1").physics("emw").feature("pec2").selection().set(new int[]{3, 4});
model.study("std1").create("freq", "Frequency");

model.component("comp1").physics().create("es", "Electrostatics", "geom1");
model.component("comp1").physics("es").create("term1", "Terminal", 2);
model.component("comp1").physics("es").feature("term1").selection().set(new int[]{2});
model.component("comp1").physics("es").feature("term1").set("TerminalType", "Voltage");
model.component("comp1").physics("es").feature("term1").set("V0", "1[V]");
model.component("comp1").physics("es").create("gnd1", "Ground", 2);
model.component("comp1").physics("es").feature("gnd1").selection().set(new int[]{5});

model.component("comp1").physics().create("mf", "InductionCurrents", "geom1");
model.component("comp1").physics("mf").create("coil1", "Coil", 3);
model.component("comp1").physics("mf").feature("coil1").selection().set(new int[]{3});
model.component("comp1").physics("mf").feature("coil1").set("ConductorModel", "Multi");
model.component("comp1").physics("mf").feature("coil1").set("CoilExcitation", "Current");
model.component("comp1").physics("mf").feature("coil1").set("ICoil", "2[A]");
model.component("comp1").physics("mf").feature("coil1").set("N", "250");

model.component("comp1").physics().create("emw", "ElectromagneticWaves", "geom1");
model.component("comp1").physics("emw").create("lport1", "LumpedPort", 2);
model.component("comp1").physics("emw").feature("lport1").selection().set(new int[]{12});
model.component("comp1").physics("emw").feature("lport1").set("PortExcitation", "on");
model.study("std1").create("freq", "Frequency");
model.study("std1").feature("freq").set("plist", "range(1[GHz],0.05[GHz],3[GHz])");

model.component("comp1").physics().create("emw", "ElectromagneticWaves", "geom1");
// GUI: Electromagnetic Waves, Frequency Domain (emw) > right-click >
// Scattering Boundary Condition, select the outer air boundaries,
// set Scattered wave type = Spherical wave and (optionally) Incident field =
// Wave given by E field with E0 = {0, 0, 1} and k_dir = {1, 0, 0}.
model.study("std1").create("freq", "Frequency");

model.component("comp1").coordSystem().create("pml1", "PML", 3);
model.component("comp1").coordSystem("pml1").selection().set(new int[]{1, 2, 3, 4});
// GUI: set Geometry type = Spherical on the PML node, then mesh the PML shell
// with a Swept mesh of 5-8 element layers in the absorbing direction.
model.component("comp1").physics().create("emw", "ElectromagneticWaves", "geom1");

model.component("comp1").physics().create("acpr", "PressureAcoustics", "geom1");
model.component("comp1").physics("acpr").create("nacc1", "NormalAcceleration", 2);
model.component("comp1").physics("acpr").feature("nacc1").selection().set(new int[]{5});
model.component("comp1").physics("acpr").create("pwr1", "PlaneWaveRadiation", 2);
model.component("comp1").physics("acpr").feature("pwr1").selection().set(new int[]{1, 6});
model.study("std1").create("freq", "Frequency");
model.study("std1").feature("freq").set("plist", "range(100, 10, 2000)");

model.component("comp1").physics().create("actd", "TransientPressureAcoustics", "geom1");
model.component("comp1").physics("actd").create("nacc1", "NormalAcceleration", 2);
model.component("comp1").physics("actd").feature("nacc1").selection().set(new int[]{1});
model.study("std1").create("time", "Transient");
model.study("std1").feature("time").set("tlist", "range(0, 1e-6, 2e-3)");

model.component("comp1").physics().create("ta", "ThermoacousticsSinglePhysics", "geom1");
// GUI: add Boundary Layer meshes on all walls so that the viscous and thermal
// penetration depths (ta.d_visc, ta.d_therm) are resolved by several elements.
model.study("std1").create("freq", "Frequency");
model.study("std1").feature("freq").set("plist", "range(20, 20, 20000)");

model.component("comp1").physics().create("tds", "DilutedSpecies", "geom1");
model.component("comp1").physics("tds").create("in1", "Inflow", 2);
model.component("comp1").physics("tds").feature("in1").selection().set(new int[]{1});
model.component("comp1").physics("tds").feature("in1").set("c0", new String[]{"1[mol/m^3]"});
model.component("comp1").physics("tds").create("out1", "Outflow", 2);
model.component("comp1").physics("tds").feature("out1").selection().set(new int[]{6});

// GUI: Add Component > 0D, then Add Physics > Chemical Species Transport >
// Reaction Engineering (re). Right-click re > Reaction and type "A+2B=>C";
// set the Arrhenius parameters on the Reaction node, choose Reactor type = Batch,
// then add a Time Dependent study and plot the species concentrations.
// Finally use re > Generate Space-Dependent Model to build the 3D reactor model.

// GUI: Add Physics > Electrochemistry > Primary and Secondary Current Distribution >
// Secondary Current Distribution. On the Electrolyte node set sigma_l;
// right-click > Electrode Surface on the anode and add an Electrode Reaction
// with Butler-Volmer kinetics (i0, alpha_a, alpha_c, Eeq);
// set the cathode Electrode Surface to Electric Ground and solve a Stationary study.

model.component("comp1").physics().create("semi", "Semiconductor", "geom1");
// GUI: Semiconductor (semi) > Semiconductor Material Model 1 - pick the material;
// right-click > Analytic Doping Model for the n and p regions;
// right-click > Metal Contact on the anode (Terminal type = Voltage) and cathode (Ground).
model.study("std1").create("stat", "Stationary");

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
// GUI: Add Physics > Fluid Flow > Particle Tracing > Particle Tracing for Fluid Flow (fpt).
// Add fpt > right-click > Drag Force (Velocity field = spf), > Gravity, and an Inlet
// releasing 1000 particles on the inlet face. Study 1: Stationary (spf),
// Study 2: Time Dependent with Particle Tracing selected.
model.study("std2").create("time", "Transient");

model.component("comp1").physics().create("c", "CoefficientFormPDE", "geom1");
model.component("comp1").physics("c").feature("cfeq1").set("c", new String[]{"1"});
model.component("comp1").physics("c").feature("cfeq1").set("a", new String[]{"0"});
model.component("comp1").physics("c").feature("cfeq1").set("f", new String[]{"1"});
model.component("comp1").physics("c").create("dir1", "DirichletBoundary", 2);
model.component("comp1").physics("c").feature("dir1").selection().set(new int[]{1, 2, 3, 4});

model.component("comp1").physics().create("g", "GeneralFormPDE", "geom1");
model.component("comp1").physics("g").feature("gfeq1").set("Ga", new String[][]{{"-(1+u^2)*ux"}, {"-(1+u^2)*uy"}, {"-(1+u^2)*uz"}});
model.component("comp1").physics("g").feature("gfeq1").set("f", new String[]{"1"});
model.component("comp1").physics("g").feature("gfeq1").set("da", new String[]{"1"});
model.component("comp1").physics("g").create("dir1", "DirichletBoundary", 2);
model.component("comp1").physics("g").feature("dir1").selection().set(new int[]{1});

model.component("comp1").physics().create("ge", "GlobalEquations", "geom1");
// GUI: Global ODEs and DAEs (ge) > Global Equations - enter
//   Name: Q      f: Q - k_p*(T_set - comp1.aveop1(T))      Initial value: 0
// where aveop1 is an Average coupling operator defined under Component > Definitions.
// The variable Q can then be used directly as the Heat Source in ht.
model.study("std1").create("time", "Transient");

model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
model.component("comp1").physics().create("ht", "HeatTransfer", "geom1");
model.multiphysics().create("te1", "ThermalExpansion", "geom1", 3);
model.multiphysics().create("tc1", "TemperatureCoupling", "geom1", -1);

model.component("comp1").physics().create("ec", "ConductiveMedia", "geom1");
model.component("comp1").physics().create("ht", "HeatTransfer", "geom1");
model.multiphysics().create("emh1", "ElectromagneticHeating", "geom1", 3);
model.study("std1").create("stat", "Stationary");

model.component("comp1").physics().create("spf", "LaminarFlow", "geom1");
model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
// GUI: Multiphysics > Fluid-Structure Interaction - choose spf as the fluid interface,
// solid as the structure interface, and let COMSOL add the Moving Mesh /
// Deforming Domain node on the fluid domain automatically.
model.study("std1").create("time", "Transient");

model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
model.component("comp1").physics().create("es", "Electrostatics", "geom1");
// GUI: Multiphysics > Piezoelectric Effect, then add a Piezoelectric Material node
// under solid and a Charge Conservation, Piezoelectric node under es on the same domains.
model.study("std1").create("eig", "Eigenfrequency");

model.component("comp1").physics().create("acpr", "PressureAcoustics", "geom1");
model.component("comp1").physics().create("solid", "SolidMechanics", "geom1");
// GUI: Multiphysics > Acoustic-Structure Boundary - select the wetted boundaries
// between the acoustic domain and the solid.
model.study("std1").create("freq", "Frequency");
model.study("std1").feature("freq").set("plist", "range(20, 5, 2000)");
